// Result contains the configuration and warnings produced while loading it.
type Result struct {
	Config   *Config
	Warnings []string
}

func Load(path string) (*Result, error) {
	v := viper.New()
	v.SetEnvPrefix("FLIPT")
	v.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
